from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    G={}
    for fp in sorted(glob.glob(d+'/../../sessions/*.jsonl')):
        t=open(fp).read().replace('\\n','\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            k,h,w=m[1],int(m[2]),int(m[3])
            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(g,bg):
    g=np.array(g); H,W=g.shape; seen=np.zeros((H,W),bool); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]==bg or seen[i,j]: continue
            st=[(i,j)]; seen[i,j]=1; pts=[]
            while st:
                y,x=st.pop(); pts.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==g[i,j] and not seen[ny,nx]:
                            seen[ny,nx]=1; st.append((ny,nx))
            out.append((pts,g[i,j]))
    return out
def f(g):
    g=[r[:] for r in g]; bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    for pts,c in comps_of(g,bg):
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        for (y,x) in pts:
            if y!=r0 and y!=r1 and x!=c0 and x!=c1:
                g[y][x]=8
    return g
